css:
@page {
    /*size: A5 landscape;*/
    margin-left: 15mm;
    margin-right: 5mm;
    margin-top: 5mm;
}

@media screen {
		.print-format {
			width: 210mm;
			height: auto;
			font-size: 10px;
			margin:-25px;
		}
	
	}
.action-banner {
    display: none !important;
}

.print-format {
font-family: Arial, Helvetica, sans-serif;
    padding-top: 15px !important;
    padding-bottom: 15px !important;
    padding-left: 35px !important;
    padding-right: 5px !important;
    
    border-spacing: 0 !important;
    font-size: 10px;
    margin-left:5px;
    margin-top:5px;
    margin-right:5px;
    margin-bottom:5px;
}

.voucher-container {
    border: 1px solid #2c3e50;
    border-radius: 10px;
    padding: 5px;
    overflow: hidden;
}

.voucher-header {
    text-align: center;
    background: #f4f6f8;
    border: 1px solid #dcdcdc;
    border-radius: 5px;
    margin-bottom: 5px;
}

.voucher-header h3 {
    margin: 0;
    font-size: 14px;
    letter-spacing: 1px;
    color: #2c3e50;
    padding:5px;
}

.details-table{
    width: 100%;
}

.customer-section,
.voucher-section {
    border: 1px solid #bfc7cf;
    border-radius: 8px;
    padding: 8px;
    vertical-align: top;
    font-size: 12px;
}

.item-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    font-size: 12px;
    margin-top:5px;
    text-align: center;
}

.item-table th,
.item-table td {
    border: 1px solid #bfc7cf;
    padding: 8px;
    vertical-align: top;
}

/* Column widths */
.item-table th:nth-child(1),
.item-table td:nth-child(1) {
    width: 12%;
    font-weight: bold;
    font-size: 12px;
}

.item-table th:nth-child(2),
.item-table td:nth-child(2) {
    width: 18%;
}

.item-table th:nth-child(3),
.item-table td:nth-child(3) {
    width: 35%;
}

.item-table th:nth-child(4),
.item-table td:nth-child(4) {
    width: 35%;
}

.item-table th {
    background: #f4f6f8;
    text-align: center;
}

.sticker-box {
    height: 80px;
    background: #fff;
}

.declaration {
    margin-top: 12px;
    padding: 8px;
    border: 1px dashed #999;
    border-radius: 8px;
    font-size: 10px;
}

.signature-table {
width: 100%;
margin-top: 40px;
border: none;
}

.signature-table td {
width: 50%;
text-align: center;
border: none;
padding-top: 35px;
font-weight: bold;
}

@media print {
.items-table tr {
    page-break-inside: avoid;
}

.voucher-container {
    border: 2px solid #222;
}

}
